/*
 * prog37_binomial_coefficient
 *
 * Re‑implementation of the original binary (which was heavily obfuscated).
 * The program expects exactly two command‑line arguments:
 *
 *     prog N K
 *
 *   N – the size of the set (0 ≤ N ≤ 60)
 *   K – the size of the subset (any integer, the binomial coefficient
 *       C(N,K) is defined as 0 when K<0 or K>N)
 *
 * Behaviour
 * ----------
 *   * If the program is invoked with fewer than two arguments
 *       it prints:
 *
 *           NO_INPUT
 *
 *   * If either argument cannot be parsed as a base‑10 integer
 *     (i.e. the whole string is not a valid integer) it prints:
 *
 *           BAD_INPUT
 *
 *   * If N is outside the allowed range (N < 0 or N > 60) it prints:
 *
 *           OUT_OF_RANGE
 *
 *   * Otherwise it computes the binomial coefficient C(N,K) using
 *     a simple recursive definition with memoisation and prints the
 *     result as a signed 64‑bit integer followed by a newline.
 *
 * The implementation below follows the same logical flow but is
 * written in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

#define MAX_N 60

/* ------------------------------------------------------------------ */
/* Memoisation table for binomial coefficients.                       */
/* memo[n][k] stores C(n,k) for 0 ≤ n ≤ MAX_N and 0 ≤ k ≤ n.          */
/* A separate table `computed` records whether a value has already   */
/* been calculated.                                                   */
/* ------------------------------------------------------------------ */
static long long memo[MAX_N + 1][MAX_N + 1];
static char     computed[MAX_N + 1][MAX_N + 1];

/* ------------------------------------------------------------------ */
/* Recursive binomial coefficient with memoisation.                   */
/* Returns C(n,k) for all integer arguments.                          */
/*   - If k < 0 or k > n   → 0                                      */
/*   - If k == 0 or k == n → 1                                      */
/*   - Otherwise C(n,k) = C(n‑1,k‑1) + C(n‑1,k)                      */
/* ------------------------------------------------------------------ */
static long long binom(int n, int k)
{
    if (k < 0 || k > n)
        return 0;
    if (k == 0 || k == n)
        return 1;

    if (computed[n][k])
        return memo[n][k];

    long long v = binom(n - 1, k - 1) + binom(n - 1, k);
    memo[n][k] = v;
    computed[n][k] = 1;
    return v;
}

/* ------------------------------------------------------------------ */
/* Helper: parse a string as a base‑10 integer, ensuring the whole     */
/* string is consumed and that the value fits into a signed 32‑bit    */
/* integer (the original program used `int` for the arguments).      */
/* Returns 0 on success, non‑zero on failure.                         */
/* ------------------------------------------------------------------ */
static int parse_int(const char *s, int *out)
{
    char *endptr;
    long val;

    errno = 0;
    val = strtol(s, &endptr, 10);

    /* No digits at all, or extra characters after the number? */
    if (endptr == s || *endptr != '\0')
        return -1;               /* BAD_INPUT */

    /* Out of range for a 32‑bit signed int? */
    if (errno == ERANGE || val < INT_MIN || val > INT_MAX)
        return -1;               /* BAD_INPUT */

    *out = (int)val;
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    int n, k;
    if (parse_int(argv[1], &n) != 0 || parse_int(argv[2], &k) != 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0 || n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long result = binom(n, k);
    printf("%lld\n", result);
    return 0;
}
